 3	import android.content.Context;
 4	
 5	import androidx.annotation.NonNull;
 6	import androidx.annotation.Nullable;
 7	
 8	import com.termux.shared.android.PackageUtils;
 9	import com.termux.shared.logger.Logger;
10	import com.termux.shared.settings.preferences.AppSharedPreferences;
11	import com.termux.shared.settings.preferences.SharedPreferenceUtils;
12	import com.termux.shared.termux.TermuxUtils;
13	
14	abstract class TermuxPackageAppSharedPreferences extends AppSharedPreferences {
15	
16	    @FunctionalInterface
17	    protected interface PreferencesFactory<T extends TermuxPackageAppSharedPreferences> {
18	        T create(@NonNull Context packageContext);
19	    }
20	
21	    protected TermuxPackageAppSharedPreferences(@NonNull Context context, @NonNull String preferencesFileBasename) {
22	        super(context,
23	            SharedPreferenceUtils.getPrivateSharedPreferences(context, preferencesFileBasename),
24	            SharedPreferenceUtils.getPrivateAndMultiProcessSharedPreferences(context, preferencesFileBasename));
25	    }
26	
27	    @Nullable
28	    protected static <T extends TermuxPackageAppSharedPreferences> T buildPreferences(@NonNull Context context,
29	                                                                                       @NonNull String packageName,
30	                                                                                       boolean exitAppOnError,
31	                                                                                       @NonNull PreferencesFactory<T> factory) {
32	        Context packageContext = exitAppOnError
33	            ? TermuxUtils.getContextForPackageOrExitApp(context, packageName, exitAppOnError)
34	            : PackageUtils.getContextForPackage(context, packageName);
35	        if (packageContext == null) return null;
36	
37	        return factory.create(packageContext);
38	    }
39	
40	    protected int getStoredLogLevel(@NonNull String key, boolean readFromFile) {
41	        return SharedPreferenceUtils.getInt(readFromFile ? mMultiProcessSharedPreferences : mSharedPreferences,
42	            key, Logger.DEFAULT_LOG_LEVEL);
43	    }
44	
45	    protected void setStoredLogLevel(@NonNull Context context, @NonNull String key, int logLevel,
46	                                     boolean commitToFile) {
47	        SharedPreferenceUtils.setInt(mSharedPreferences, key, Logger.setLogLevel(context, logLevel), commitToFile);
48	    }
49	
50	    protected boolean getStoredBoolean(@NonNull String key, boolean defaultValue, boolean readFromFile) {
51	        return SharedPreferenceUtils.getBoolean(readFromFile ? mMultiProcessSharedPreferences : mSharedPreferences,
52	            key, defaultValue);
53	    }
54	
55	    protected void setStoredBoolean(@NonNull String key, boolean value, boolean commitToFile) {
56	        SharedPreferenceUtils.setBoolean(mSharedPreferences, key, value, commitToFile);
57	    }
58	
59	}

 1	package com.termux.shared.termux.settings.preferences;
 2	
 3	import android.content.Context;
 4	import android.util.TypedValue;
 5	
 6	import androidx.annotation.NonNull;
 7	
 8	import com.termux.shared.data.DataUtils;
 9	import com.termux.shared.settings.preferences.SharedPreferenceUtils;
10	
11	abstract class TermuxFontSizeAppSharedPreferences extends TermuxPackageAppSharedPreferences {
12	
13	    private final int mMinFontSize;
14	    private final int mMaxFontSize;
15	    private final int mDefaultFontSize;
16	
17	    protected TermuxFontSizeAppSharedPreferences(@NonNull Context context,
18	                                                 @NonNull String preferencesFileBasename) {
19	        super(context, preferencesFileBasename);
20	
21	        int[] sizes = getDefaultFontSizes(context);
22	        mDefaultFontSize = sizes[0];
23	        mMinFontSize = sizes[1];
24	        mMaxFontSize = sizes[2];
25	    }
26	
27	    public static int[] getDefaultFontSizes(@NonNull Context context) {
28	        float dipInPixels = TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, 1,
29	            context.getResources().getDisplayMetrics());
30	
31	        int[] sizes = new int[3];
32	
33	        // This is a bit arbitrary and sub-optimal. We want to give a sensible default for minimum
34	        // font size to prevent invisible text due to zoom by mistake.
35	        sizes[1] = (int) (4f * dipInPixels);
36	
37	        // http://www.google.com/design/spec/style/typography.html#typography-line-height
38	        int defaultFontSize = Math.round(12 * dipInPixels);
39	        if (defaultFontSize % 2 == 1) defaultFontSize--;
40	
41	        sizes[0] = defaultFontSize;
42	        sizes[2] = 256;
43	
44	        return sizes;
45	    }
46	
47	    protected abstract String getFontSizePreferenceKey();
48	
49	    public int getFontSize() {
50	        int fontSize = SharedPreferenceUtils.getIntStoredAsString(mSharedPreferences,
51	            getFontSizePreferenceKey(), mDefaultFontSize);
52	        return DataUtils.clamp(fontSize, mMinFontSize, mMaxFontSize);
53	    }
54	
55	    public void setFontSize(int value) {
56	        SharedPreferenceUtils.setIntStoredAsString(mSharedPreferences, getFontSizePreferenceKey(),
57	            value, false);
58	    }
59	
60	    public void changeFontSize(boolean increase) {
61	        int fontSize = getFontSize();
62	        fontSize += (increase ? 1 : -1) * 2;
63	        fontSize = Math.max(mMinFontSize, Math.min(fontSize, mMaxFontSize));
64	        setFontSize(fontSize);
65	    }
66	
67	}

